Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Gets/sets the pick list number
/// </summary>
/// <param name = "_pickingRouteId">pick list number</param>
/// <returns>return the pick list number</returns>
[DataMemberAttribute('PickListNumber')]
public WMSPickingRouteID parmPickingRouteId(WMSPickingRouteID _pickingRouteId = pickingRouteId)
{
    pickingRouteId = _pickingRouteId;
    return pickingRouteId;
}
